// 占位符填充工具：仅替换 pages/page-N.pptx.html 中的 {{KEY}} 占位符，不改动模板骨架。
// 输入：fill/page-N.json（标量占位符）+ fill/page-N.content.html（可选，PAGE_CONTENT 片段）
import fs from 'node:fs';
import path from 'node:path';

const root = process.argv[2] || process.cwd();
const pagesDir = path.join(root, 'pages');
const fillDir = path.join(root, 'fill');

const files = fs.readdirSync(fillDir).filter((f) => /^page-\d+\.json$/.test(f)).sort((a, b) => {
  const na = Number(a.match(/\d+/)[0]);
  const nb = Number(b.match(/\d+/)[0]);
  return na - nb;
});

let failed = false;
for (const file of files) {
  const n = Number(file.match(/\d+/)[0]);
  const pagePath = path.join(pagesDir, `page-${n}.pptx.html`);
  const map = JSON.parse(fs.readFileSync(path.join(fillDir, file), 'utf8'));
  const fragPath = path.join(fillDir, `page-${n}.content.html`);
  if (fs.existsSync(fragPath)) {
    map.PAGE_CONTENT = fs.readFileSync(fragPath, 'utf8').trim();
  }
  let html = fs.readFileSync(pagePath, 'utf8');
  for (const [key, value] of Object.entries(map)) {
    html = html.split(`{{${key}}}`).join(value);
  }
  fs.writeFileSync(pagePath, html);
  const left = [...html.matchAll(/\{\{[A-Z][A-Z0-9_]*\}\}/g)].map((m) => m[0]);
  const uniq = [...new Set(left)];
  console.log(`page-${n}: filled ${Object.keys(map).length} keys, remaining=${uniq.length ? uniq.join(',') : 'none'}`);
  if (uniq.length) failed = true;
}
process.exit(failed ? 1 : 0);

