  const tmp = `/tmp/measure-${n}.html`;
  fs.writeFileSync(tmp, html);
  await page.goto('file://' + tmp);
  await page.waitForTimeout(2500);
  const data = await page.evaluate(() => {
    const out = [];
    const main = document.querySelector('main');
    const mrect = main.getBoundingClientRect();
    const inkOf = (el) => {
      let top = Infinity, bottom = -Infinity;
      const walk = (node) => {
        for (const child of node.childNodes) {
          if (child.nodeType === 3) {
            const t = child.textContent.trim();
            if (!t) continue;
            const r = document.createRange();
            r.selectNodeContents(child);
            const b = r.getBoundingClientRect();
            if (b.height > 0) { top = Math.min(top, b.top); bottom = Math.max(bottom, b.bottom); }
          } else if (child.nodeType === 1) {
            if (child.tagName === 'SCRIPT' || child.tagName === 'STYLE') continue;
            const cs = getComputedStyle(child);
            if (child.getBoundingClientRect().height > 0 && (cs.backgroundColor !== 'rgba(0, 0, 0, 0)' || cs.borderTopWidth !== '0px')) {
              const b = child.getBoundingClientRect();
              top = Math.min(top, b.top); bottom = Math.max(bottom, b.bottom);
            }
            walk(child);
          }
        }
      };
      walk(el);
      return { top, bottom };
    };
    const report = (el, label) => {
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      const ink = inkOf(el);
      const padTop = parseFloat(cs.paddingTop), padBottom = parseFloat(cs.paddingBottom);
      const contentTop = r.top + padTop + parseFloat(cs.borderTopWidth);
      const contentBottom = r.bottom - padBottom - parseFloat(cs.borderBottomWidth);
      out.push({
        label,
        h: +r.height.toFixed(1),
        contentBox: +(contentBottom - contentTop).toFixed(1),
        inkH: +(ink.bottom - ink.top).toFixed(1),
        freeInContentBox: +(contentBottom - contentTop - (ink.bottom - ink.top)).toFixed(1),
        pct: +(((contentBottom - contentTop) - (ink.bottom - ink.top)) / r.height * 100).toFixed(1),
        bottomGap: +(contentBottom - ink.bottom).toFixed(1),
        topGap: +(ink.top - contentTop).toFixed(1),
      });
    };
    report(main, 'MAIN');
    const root = main.firstElementChild;
    if (root) report(root, 'ROOT');
    document.querySelectorAll('main section, main aside, main div.border, main aside > div').forEach((el, i) => {
      const cls = (el.className || '').toString().slice(0, 60);
      report(el, `[${i}] ${cls}`);
    });
    return { mainH: +mrect.height.toFixed(1), out };
  });
  console.log(`\n===== page-${n} (main height ${data.mainH}) =====`);
  for (const r of data.out) {
    console.log(`${r.label.padEnd(64)} h=${String(r.h).padStart(6)} cbox=${String(r.contentBox).padStart(6)} ink=${String(r.inkH).padStart(6)} free=${String(r.freeInContentBox).padStart(6)} pct=${String(r.pct).padStart(5)}% topGap=${r.topGap} bottomGap=${r.bottomGap}`);
  }
}
